'use client'

import { useId, type MouseEvent, type ReactNode, type Ref } from 'react'
import { Field } from '@base-ui/react/field'
import { Popover } from '@base-ui/react/popover'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './InputField.module.css'

export type ValidationState = 'default' | 'success' | 'error'
export type InputSize = 'sm' | 'md'

/**
 * The shared classes. `box` goes on the element that draws the field (the
 * border, fill and focus ring); `control` on the <input>/<textarea> inside
 * it; `affix` on a prefix or suffix.
 */
export const inputStyles = styles

/** The class list for a field box of this size. */
export function boxClass(size: InputSize) {
  return cn(styles.box, styles[size])
}

/**
 * For the box's onMouseDown: a press on its padding or a prefix focuses the
 * control, as a click anywhere on a native field would. Presses on the
 * control itself or on a button in the box are left alone.
 */
export function focusControl(event: MouseEvent<HTMLElement>) {
  const target = event.target as HTMLElement
  if (target.closest('input, textarea, button')) return
  const control = event.currentTarget.querySelector<HTMLElement>('input, textarea')
  if (!control || control.matches(':disabled')) return
  event.preventDefault()
  control.focus()
}

/** Hand a node to a ref prop of either kind, alongside a component's own. */
export function assignRef<T>(ref: Ref<T> | undefined, node: T | null) {
  if (typeof ref === 'function') ref(node)
  else if (ref) ref.current = node
}

export interface InputFieldProps {
  /** The field box, carrying `boxClass()`, with a Field.Control inside. */
  children: ReactNode
  label?: ReactNode
  /** More about the label, behind an info button after it. */
  labelInfo?: ReactNode
  /** The info button's accessible name; the label is read after it. */
  infoLabel?: string
  helperText?: ReactNode
  validationState?: ValidationState
  required?: boolean
  disabled?: boolean
  name?: string
  isFullWidth?: boolean
  /**
   * For a control that is a button (Select's trigger): render the label as a
   * <div> so clicking it focuses the control without also clicking it.
   */
  hasButtonControl?: boolean
  /** An id for the label, for a part beyond the control that it also names. */
  labelId?: string
  /** After the helper text, inside the field: an action on the whole field. */
  footer?: ReactNode
  className?: string
}

/**
 * The label, helper text and validation wiring shared by Text Input,
 * Textarea, Search and Number Input. Base UI's Field associates the label
 * with the control, makes the helper its description and puts
 * aria-invalid on it. Internal — not exported from the package.
 */
export function InputField({
  children,
  label,
  labelInfo,
  infoLabel = 'More information',
  helperText,
  validationState = 'default',
  required,
  disabled,
  name,
  isFullWidth,
  hasButtonControl,
  labelId,
  footer,
  className,
}: InputFieldProps) {
  const ownLabelId = useId()
  const resolvedLabelId = labelId ?? ownLabelId
  const labelNode = label && (
    <Field.Label
      id={resolvedLabelId}
      className={styles.label}
      {...(hasButtonControl && { nativeLabel: false, render: <div /> })}
    >
      {label}
      {required && (
        <span aria-hidden="true" className={styles.required}>
          *
        </span>
      )}
    </Field.Label>
  )
  return (
    <Field.Root
      name={name}
      disabled={disabled}
      invalid={validationState === 'error'}
      className={cn(styles.field, styles[`state-${validationState}`], isFullWidth && styles.fullWidth, className)}
    >
      {labelInfo && labelNode ? (
        <div className={styles.labelRow}>
          {labelNode}
          {/* A toggletip, not a tooltip: it opens on tap and stays open to be
              read, and the button sits outside the <label> so pressing it does
              not also focus the control. */}
          <Popover.Root>
            <Popover.Trigger className={styles.iconButton} aria-label={infoLabel} aria-describedby={resolvedLabelId}>
              <Icon name="info" />
            </Popover.Trigger>
            <Popover.Portal>
              <Popover.Positioner className={styles.positioner} side="top" sideOffset={6}>
                <Popover.Popup className={styles.info} aria-labelledby={resolvedLabelId}>{labelInfo}</Popover.Popup>
              </Popover.Positioner>
            </Popover.Portal>
          </Popover.Root>
        </div>
      ) : (
        labelNode
      )}
      {children}
      {helperText && <Field.Description className={styles.helper}>{helperText}</Field.Description>}
      {footer}
    </Field.Root>
  )
}

/* Shared by Text Input, Textarea, Search, Number Input, Select and Combobox. */
.field {
  --field-edge: var(--color-border-input);
  display: inline-grid;
  gap: var(--space-stack);
  inline-size: 20rem;
  max-inline-size: 100%;
  font-family: var(--font-sans);
}

/* Grid items never shrink below their content by default, and an <input>'s
   content is about 20 characters wide: in a container narrower than that
   the box, or Number Input's wrapper round it, overflowed the field. */
.field > * {
  min-inline-size: 0;
}

.fullWidth {
  display: grid;
  inline-size: 100%;
}

.label {
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  /* Atlassian's form Label is bold, 653 on its variable font. */
  font-weight: var(--font-weight-label);
  color: var(--color-text);
}

/* The label and its info button. The button is out of the <label>, so
   pressing it opens the note without focusing the control. */
.labelRow {
  --field-icon: var(--icon-sm);
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.info {
  box-sizing: border-box;
  max-inline-size: min(22rem, var(--available-width));
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-surface-overlay);
  box-shadow: var(--shadow-overlay);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  outline: none;
}

.required {
  margin-inline-start: var(--space-1);
  color: var(--color-text-danger);
}

.helper {
  margin: 0;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--color-text-subtlest);
}

/* Validation changes the field's edge and its helper text together; the
   words are the message, the colour only points at it. */
.state-error {
  --field-edge: var(--color-text-danger);
}
.state-error .helper {
  color: var(--color-text-danger);
}
.state-success {
  --field-edge: var(--color-text-success);
}
.state-success .helper {
  color: var(--color-text-success);
}

/* ------------------------------------------------------------------ box
   The box draws the field; the control inside it is bare. The edge is
   --color-border-input, a light hairline (about 1.5:1, as in the Claude apps),
   not the 3:1 --color-border-bold: a deliberate exception to WCAG 1.4.11,
   approved 2026-10-08. The outlined field makes up for it by being a white
   card on the off-white page, and the label, placeholder and focus ring
   still mark it. Checkbox, radio and switch keep 3:1. */
.box {
  display: flex;
  align-items: center;
  box-sizing: border-box;
  inline-size: 100%;
  /* Inside Number Input's wrapper the box is a block, not a grid item. */
  min-inline-size: 0;
  border: 1px solid var(--field-edge);
  background: var(--color-surface-raised);
  color: var(--color-text);
  cursor: text;
  transition: border-color var(--duration-base);
}

/* A field is one step taller than a button, after Atlassian: md is
   --control-lg (40px) and sm is --control-md (32px), which lines up with a
   Button in a toolbar. Both sizes share the rest: 10px of padding inside the
   edge (the Figma library's binding), the md icon and gap, the field radius
   (which never becomes a pill) and body type. Every icon in the box (affix,
   chevron, clear, stepper, spinner) reads --field-icon. */
.sm,
.md {
  --field-pad: var(--space-2-5);
  --field-icon: var(--icon-md);
  --field-radius: var(--control-md-radius-field);
  /* 8px, not the control tier's 6px gap: a 24px button in the box is pulled
     out 4px each side, so two of them touch and an icon keeps 8px from text. */
  gap: var(--space-2);
  padding-inline: var(--field-pad);
  border-radius: var(--field-radius);
  font-size: var(--text-body);
  line-height: var(--leading-body);
}
.sm {
  min-block-size: var(--control-md);
}
.md {
  min-block-size: var(--control-lg);
}

/* A field that opens a list (Select, Combobox) keeps the text fields'
   padding and 16px icon, but 12px between the value, the clear icon and the
   chevron. After .sm and .md, so it wins at equal specificity. */
.picker {
  gap: var(--space-3);
}

/* Date Picker's calendar button sits 8px after the value, as a text field's
   suffix. After .picker, so it wins at equal specificity. */
.datePicker {
  gap: var(--space-2);
}

/* The ring is on the box, drawn when the control inside has keyboard or
   pointer focus — a text field shows focus on click too, since that is
   where typing will go. */
/* Keyed to the control: a clear or open button inside the field draws its
   own ring, and a second one round the whole field would double it.
   A Select keeps the ring while its list is open: focus has moved into
   the list, but the field is still the one being chosen for. */
.box:has(.control:focus),
.box:focus-visible,
.box[data-popup-open] {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset);
}

.state-error .box:has(.control:focus),
.state-error .box:focus-visible,
.state-error .box[data-popup-open] {
  outline-color: var(--color-text-danger);
}

/* Keyed to the control, not any descendant: a stepper button disabled at
   its limit must not dim the whole field. `.box:disabled` is a trigger that
   is its own box (Select) inside a disabled <fieldset>, which Base UI's
   data-disabled does not see. */
.box:has(.control:disabled),
.box:disabled,
.box[data-disabled] {
  cursor: var(--cursor-disabled);
  opacity: 0.5;
}

.box:has(.control[readonly]),
.box[data-readonly] {
  background: var(--color-background-input);
}

/* ------------------------------------------------------------- control */
.control {
  flex: 1;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
  outline: none; /* the box draws the ring */
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: inherit;
}

.control::placeholder {
  color: var(--color-text-subtlest);
  opacity: 1;
}

.affix {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  color: var(--color-text-subtlest);
  white-space: nowrap;
}

.affix > svg {
  font-size: var(--field-icon);
}

/* ------------------------------------------------------------ add-ons
   A filled segment at the box's edge (Text Input's startAddon/endAddon),
   divided from the value by a hairline in the edge colour, so the field
   still reads as one box and takes the validation colour as one. It cancels
   the box's padding on its side and runs the full height. */
.addon {
  display: inline-flex;
  align-items: center;
  align-self: stretch;
  flex-shrink: 0;
  padding-inline: var(--field-pad);
  background: var(--color-background-input);
  color: var(--color-text-subtlest);
  white-space: nowrap;
}
/* The corners follow the box's inner curve: its radius less the 1px edge. */
.addonStart {
  margin-inline-start: calc(-1 * var(--field-pad));
  border-inline-end: 1px solid var(--field-edge);
  border-start-start-radius: calc(var(--field-radius) - 1px);
  border-end-start-radius: calc(var(--field-radius) - 1px);
}
.addonEnd {
  margin-inline-end: calc(-1 * var(--field-pad));
  border-inline-start: 1px solid var(--field-edge);
  border-start-end-radius: calc(var(--field-radius) - 1px);
  border-end-end-radius: calc(var(--field-radius) - 1px);
}
.addon > svg {
  font-size: var(--field-icon);
}

/* A button in an add-on fills it, so the whole segment is the target, and
   reads as an action: body text in the foreground colour, not muted. */
.addon:has(> .iconButton) {
  padding-inline: 0;
}
.addon > .iconButton {
  align-self: stretch;
  align-items: center;
  gap: var(--space-1);
  padding-inline: var(--field-pad);
  border-radius: inherit;
  color: var(--color-text);
  font: inherit;
  font-weight: 500;
}
.addon > .iconButton:not(:disabled):hover {
  background: var(--color-background-neutral);
}
/* Inside the segment, so the ring is not cut by the box's edge. */
.addon > .iconButton:focus-visible {
  outline-offset: calc(-1 * var(--focus-width));
}
.addon > .iconButton > svg {
  font-size: var(--field-icon);
}

/* ---------------------------------------------------------------- popup
   The option list shared by Select and Combobox. It renders in a portal
   at the end of <body>, so it reads the tokens from the root: a Theme
   scope around the field does not reach it. */
/* 50: above page content and sticky headers. Modal and Popover share the
   layer: overlays portal to the end of <body>, so the one opened last is
   on top, and a list opened inside a modal shows above it. */
.positioner {
  z-index: var(--layer-overlay);
  outline: none;
}

.popup {
  box-sizing: border-box;
  min-inline-size: var(--anchor-width);
  /* 20rem is about ten options: enough to scan, short enough to stay near
     the field. The rest scrolls. */
  max-block-size: min(var(--available-height), 20rem);
  overflow-y: auto;
  /* 8px above and below the options, as Atlassian's Select menu. */
  padding-block: var(--space-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-surface-overlay);
  box-shadow: var(--shadow-overlay);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  transform-origin: var(--transform-origin);
  transition:
    opacity var(--duration-fast),
    scale var(--duration-fast);
}

.popup[data-starting-style],
.popup[data-ending-style] {
  opacity: 0;
  scale: 0.98;
}

.option {
  display: grid;
  grid-template-columns: var(--space-4) 1fr;
  align-items: center;
  gap: var(--space-2);
  min-block-size: var(--control-md);
  /* Atlassian's Select option: 6px above and below a 20px line, a 32px
     row, and 12px at the sides. */
  padding: var(--space-1-5) var(--space-3);
  cursor: default;
  user-select: none;
  outline: none;
}

/* The highlighted option is where arrow keys are: the subtle surface, as
   for any hover. Its text stays --color-text, 16:1 or more. */
.option[data-highlighted] {
  background: var(--color-background-neutral);
  color: var(--color-text);
}

.option[data-disabled] {
  color: var(--color-text-subtlest);
  opacity: 0.6;
}

/* The check sits before the label, in the brand colour. The column is kept
   whether or not the option is chosen, so labels never shift. */
.check {
  grid-column: 1;
  grid-row: 1;
  display: inline-flex;
  color: var(--color-text-brand);
  font-size: var(--icon-md);
}
.option > :not(.check) {
  grid-column: 2;
  grid-row: 1;
}

.empty,
.status {
  padding: var(--space-2) var(--space-3);
  color: var(--color-text-subtlest);
}

.empty:empty,
.status:empty {
  display: none;
}

/* Options are 32px; on touch they grow to 44px — they stack edge to edge,
   so an invisible larger area would overlap the next one. */
@media (pointer: coarse) {
  .option {
    min-block-size: var(--target-coarse);
  }
}

/* A field that is a button (Select) or has buttons in it (Combobox). */
.trigger {
  justify-content: space-between;
  /* The trigger is a <button>: WebKit's default block padding made it
     taller than its tier. The box sets its own inline padding. */
  padding-block: 0;
  text-align: start;
  /* The family only: `font: inherit` also reset the size and leading the
     size class sets, so a small Select drew 14px text in a 13px field. */
  font-family: inherit;
  cursor: var(--cursor-button);
}

.value[data-placeholder] {
  color: var(--color-text-subtlest);
}

.value {
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--color-text-subtlest);
  font-size: var(--field-icon);
}

.iconButton {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text-subtlest);
  font-size: var(--field-icon);
  cursor: var(--cursor-button);
}
.iconButton:not(:disabled):hover {
  color: var(--color-text);
}
.iconButton:disabled {
  cursor: var(--cursor-disabled);
}
/* Disabled on its own, in a field that is not: dim it as the field would be.
   In a disabled field the box already dims everything. */
.box:not(:has(.control:disabled)) .iconButton:disabled {
  opacity: 0.5;
}
.iconButton:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset);
}
/* In the box (clear, open, calendar, a button in a prefix or suffix) the
   target is 24px, which fits inside either size. It is pulled out by the
   difference, so its icon sits where a plain icon would, 6px from the edge,
   and two buttons side by side touch without overlapping. */
/* :where keeps this at one class, so a component's own trigger can still
   size itself (ColorPicker's swatch). */
:where(.box, .affix) > .iconButton {
  align-items: center;
  justify-content: center;
  inline-size: var(--control-sm);
  block-size: var(--control-sm);
  margin-inline: calc((var(--field-icon) - var(--control-sm)) / 2);
}
/* Inside the target, so the ring is not cut by the box's edge. */
:where(.box, .affix) > .iconButton:focus-visible {
  outline-offset: var(--focus-offset-inset);
}
/* A bare icon button (Combobox's clear): the 16px icon is the whole button,
   with no 24px frame round it. The picker's 12px gaps keep it clear of its
   neighbours, and on touch the ::after below still makes it 44px. */
.box > .iconButton.bare {
  inline-size: var(--field-icon);
  block-size: var(--field-icon);
  margin-inline: 0;
}

@media (pointer: coarse) {
  .iconButton::after {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: var(--target-coarse);
    block-size: var(--target-coarse);
    translate: -50% -50%;
  }
}

/* A small ring of currentColor, as Button's loading state. */
.spinner {
  inline-size: var(--field-icon);
  block-size: var(--field-icon);
  box-sizing: border-box;
  border: 2px solid currentColor;
  border-block-start-color: transparent;
  border-radius: var(--radius-pill);
  animation: field-spin var(--duration-spin) linear infinite;
}
@keyframes field-spin {
  to {
    rotate: 1turn;
  }
}
@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation-duration: var(--duration-spin-reduced);
  }
}
